41	/// Configuration for the print watcher.
42	#[derive(Debug, Clone)]
43	pub struct PrintWatcherConfig {
44	    /// Maximum number of pages to parse from XPS spool files.
45	    pub max_pages: usize,
46	    /// Action when a job cannot be classified ("ALLOW" or "DENY"/"Block").
47	    pub unclassifiable_action: String,
48	}
49	
50	impl Default for PrintWatcherConfig {
51	    fn default() -> Self {
52	        Self {
53	            max_pages: 100,
54	            unclassifiable_action: "Block".to_string(),
55	        }
56	    }
57	}
58	
59	impl PrintWatcherConfig {
60	    /// Resolves the unclassifiable action to a boolean: `true` = deny/block.
61	    #[must_use]
62	    pub fn should_deny_unclassifiable(&self) -> bool {
63	        matches!(
64	            self.unclassifiable_action.to_ascii_lowercase().as_str(),
65	            "deny" | "block"
66	        )
67	    }
68	}
