70	/// Watches the print spooler for new jobs and enforces DLP policy.
71	pub struct PrintWatcher {
72	    offline: Arc<OfflineManager>,
73	    audit_ctx: EmitContext,
74	    runtime_handle: tokio::runtime::Handle,
75	    shutdown: Arc<AtomicBool>,
76	    handle: Option<JoinHandle<()>>,
77	    config: PrintWatcherConfig,
78	}
79	
80	impl PrintWatcher {
81	    /// Constructs a new `PrintWatcher`.
82	    pub fn new(
83	        offline: Arc<OfflineManager>,
84	        audit_ctx: EmitContext,
85	        runtime_handle: tokio::runtime::Handle,
86	    ) -> Self {
87	        Self {
88	            offline,
89	            audit_ctx,
90	            runtime_handle,
91	            shutdown: Arc::new(AtomicBool::new(false)),
92	            handle: None,
93	            config: PrintWatcherConfig::default(),
94	        }
95	    }
96	
97	    /// Sets the watcher configuration.
98	    pub fn with_config(mut self, config: PrintWatcherConfig) -> Self {
99	        self.config = config;
100	        self
101	    }
102	
103	    /// Starts the watcher thread.
104	    ///
105	    /// # Panics
106	    ///
107	    /// Panics if called twice without calling `stop()` in between.
108	    pub fn start(&mut self) {
109	        assert!(self.handle.is_none(), "PrintWatcher already started");
110	
111	        let offline = Arc::clone(&self.offline);
112	        let audit_ctx = self.audit_ctx.clone();
113	        let runtime_handle = self.runtime_handle.clone();
114	        let shutdown = Arc::clone(&self.shutdown);
115	        let config = self.config.clone();
116	
117	        self.handle = Some(thread::spawn(move || {
118	            watcher_thread(offline, audit_ctx, runtime_handle, shutdown, config);
119	        }));
120	
121	        info!("print watcher thread started");
122	    }
123	
124	    /// Signals the watcher thread to shut down and waits for it to exit.
125	    pub fn stop(&mut self) {
126	        if self.handle.is_none() {
127	            return;
128	        }
129	
130	        info!("stopping print watcher thread");
131	        self.shutdown.store(true, Ordering::Relaxed);
132	
133	        if let Some(handle) = self.handle.take() {
134	            if let Err(e) = handle.join() {
135	                error!("print watcher thread panicked: {:?}", e);
136	            } else {
137	                info!("print watcher thread stopped cleanly");
138	            }
139	        }
140	    }
141	}
142	
143	impl Drop for PrintWatcher {
144	    fn drop(&mut self) {
145	        self.stop();
146	    }
147	}
