149	// ---------------------------------------------------------------------------
150	// Watcher thread
151	// ---------------------------------------------------------------------------
152	
153	fn watcher_thread(
154	    offline: Arc<OfflineManager>,
155	    audit_ctx: EmitContext,
156	    runtime_handle: tokio::runtime::Handle,
157	    shutdown: Arc<AtomicBool>,
158	    config: PrintWatcherConfig,
159	) {
160	    // Open the local print spooler with admin access.
161	    let printer = match open_printer("\\.\\pipe\\spoolss") {
162	        Ok(p) => p,
163	        Err(e) => {
164	            error!(error = %e, "failed to open printer — watcher thread exiting");
165	            return;
166	        }
167	    };
168	
169	    // Create change notification handle.
170	    let notify_handle: HANDLE = unsafe {
171	        FindFirstPrinterChangeNotification(
172	            printer.raw(),
173	            PRINTER_CHANGE_ADD_JOB | PRINTER_CHANGE_WRITE_JOB | PRINTER_CHANGE_SET_JOB,
174	            0,
175	            None,
176	        )
177	    };
178	
179	    if notify_handle.is_invalid() {
180	        let err = unsafe { windows::Win32::Foundation::GetLastError() };
181	        error!(error = ?err, "FindFirstPrinterChangeNotification failed — watcher thread exiting");
182	        return;
183	    }
184	
185	    info!("print watcher waiting for spooler changes");
186	
187	    // Keep track of jobs we've already processed to avoid duplicate evaluation.
188	    let mut seen_jobs: std::collections::HashSet<u32> = std::collections::HashSet::new();
189	
190	    loop {
191	        if shutdown.load(Ordering::Relaxed) {
192	            break;
193	        }
194	
195	        // Wait up to 500ms for a change notification.
196	        let wait_result = unsafe { WaitForSingleObject(notify_handle, 500) };
197	
198	        if wait_result == WAIT_OBJECT_0 {
199	            // Signaled — process changes.
200	            let ok = unsafe { FindNextPrinterChangeNotification(notify_handle, None, None, None) };
201	            if !ok.as_bool() {
202	                let err = unsafe { windows::Win32::Foundation::GetLastError() };
203	                warn!(error = ?err, "FindNextPrinterChangeNotification failed");
204	                continue;
205	            }
206	
207	            // Enumerate jobs.  We scan a reasonable range of job IDs because
208	            // the spooler reuses IDs and we don't have a reliable "new job"
209	            // list from the notification without `PRINTER_NOTIFY_INFO` parsing.
210	            // In practice, checking the most recent 50 job IDs is sufficient.
211	            for job_id in 1..=50 {
212	                if shutdown.load(Ordering::Relaxed) {
213	                    break;
214	                }
215	
216	                // Skip already-processed jobs.
217	                if seen_jobs.contains(&job_id) {
218	                    continue;
219	                }
220	
221	                match get_job_info(&printer, job_id) {
222	                    Ok(job) => {
223	                        // Job exists — mark as seen.
224	                        seen_jobs.insert(job_id);
225	
226	                        // Only process jobs that are spooling (not yet printing).
227	                        if is_job_printing(job.status) {
228	                            debug!(job_id, "job already printing — skipping");
229	                            continue;
230	                        }
231	
232	                        info!(
233	                            job_id,
234	                            document = %job.document_name,
235	                            user = %job.user_name,
236	                            datatype = %job.datatype,
237	                            "job_detected"
238	                        );
239	
240	                        // Evaluate the job.
241	                        let decision = evaluate_job(&job, &config, &offline, &runtime_handle);
242	
243	                        match decision {
244	                            JobDecision::Allow => {
245	                                debug!(job_id, "job_allowed");
246	                            }
247	                            JobDecision::Cancel => {
248	                                match cancel_job(&printer, job_id) {
249	                                    Ok(()) => {
250	                                        info!(job_id, "job_cancelled");
251	                                        emit_print_audit(
252	                                            &audit_ctx,
253	                                            &job,
254	                                            EventType::Block,
255	                                            Decision::DENY,
256	                                            "Print job blocked by DLP policy",
257	                                        );
258	                                    }
259	                                    Err(e) => {
260	                                        warn!(job_id, error = %e, "SetJob cancel failed");
261	                                        emit_print_audit(
262	                                            &audit_ctx,
263	                                            &job,
264	                                            EventType::Alert,
265	                                            Decision::DENY,
266	                                            &format!("Cancel failed: {e}"),
267	                                        );
268	                                    }
269	                                }
270	                            }
271	                            JobDecision::Alert(reason) => {
272	                                warn!(job_id, reason, "job_alert");
273	                                emit_print_audit(
274	                                    &audit_ctx,
275	                                    &job,
276	                                    EventType::Alert,
277	                                    Decision::DENY,
278	                                    reason,
279	                                );
280	                            }
281	                        }
282	                    }
283	                    Err(_) => {
284	                        // Job doesn't exist — no error logging needed for expected misses.
285	                    }
286	                }
287	            }
288	        }
289	    }
290	
291	    // Clean up notification handle.
292	    let _ = unsafe { CloseHandle(notify_handle) };
293	    info!("print watcher thread exited");
294	}
