296	// ---------------------------------------------------------------------------
297	// Job evaluation
298	// ---------------------------------------------------------------------------
299	
300	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
301	enum JobDecision {
302	    Allow,
303	    Cancel,
304	    Alert(&'static str),
305	}
306	
307	fn evaluate_job(
308	    job: &JobInfo,
309	    config: &PrintWatcherConfig,
310	    offline: &Arc<OfflineManager>,
311	    runtime_handle: &tokio::runtime::Handle,
312	) -> JobDecision {
313	    // Determine classification.
314	    let classification = if job.datatype == "XPS_PASS" {
315	        let spl_path = build_spl_path(job.job_id);
316	        match std::fs::read(&spl_path) {
317	            Ok(bytes) => {
318	                match extract_text(&bytes, config.max_pages) {
319	                    Ok(text) => {
320	                        let cls = ContentClassifier::classify(&text);
321	                        debug!(job_id = job.job_id, ?cls, "XPS classification result");
322	                        cls
323	                    }
324	                    Err(e) => {
325	                        warn!(job_id = job.job_id, error = %e, "XPS parse failed — falling back to metadata");
326	                        classify_document_name(&job.document_name)
327	                    }
328	                }
329	            }
330	            Err(e) => {
331	                warn!(job_id = job.job_id, error = %e, "SPL read failed — falling back to metadata");
332	                classify_document_name(&job.document_name)
333	            }
334	        }
335	    } else {
336	        // Non-XPS jobs: metadata-only classification.
337	        classify_document_name(&job.document_name)
338	    };
339	
340	    // Build ABAC request.
341	    let request = EvaluateRequest {
342	        subject: Subject {
343	            user_sid: "S-1-0-0".to_string(), // Placeholder — real SID resolution deferred.
344	            user_name: job.user_name.clone(),
345	            groups: Vec::new(),
346	            device_trust: dlp_common::DeviceTrust::Unknown,
347	            network_location: NetworkLocation::Unknown,
348	        },
349	        resource: Resource {
350	            path: job.document_name.clone(),
351	            classification,
352	        },
353	        environment: Environment {
354	            timestamp: chrono::Utc::now(),
355	            session_id: 0,
356	            access_context: dlp_common::AccessContext::Local,
357	        },
358	        action: Action::PRINT,
359	        agent: None,
360	        source_application: None,
361	        destination_application: None,
362	        source_origin: None,
363	        destination_origin: None,
364	    };
365	
366	    // Evaluate policy.
367	    let response = runtime_handle.block_on(offline.evaluate(&request));
368	
369	    decision_from_response(response, job, config)
370	}
371	
372	/// Maps an [`EvaluateResponse`] to a [`JobDecision`].
373	fn decision_from_response(
374	    response: EvaluateResponse,
375	    job: &JobInfo,
376	    _config: &PrintWatcherConfig,
377	) -> JobDecision {
378	    match response.decision {
379	        Decision::DENY | Decision::DenyWithAlert => {
380	            if is_job_printing(job.status) {
381	                JobDecision::Alert("Job already printing — cannot cancel")
382	            } else {
383	                JobDecision::Cancel
384	            }
385	        }
386	        Decision::ALLOW | Decision::AllowWithLog => JobDecision::Allow,
387	    }
388	}
389	
390	/// Heuristic classification based on document name.
391	fn classify_document_name(name: &str) -> Classification {
392	    let lower = name.to_lowercase();
393	    if lower.contains("confidential") || lower.contains("secret") {
394	        Classification::T3
395	    } else if lower.contains("internal") {
396	        Classification::T2
397	    } else {
398	        Classification::T1
399	    }
400	}
401	
402	/// Constructs the SPL file path for a given job ID.
403	fn build_spl_path(job_id: u32) -> String {
404	    format!(r"C:\Windows\System32\spool\PRINTERS\{job_id}.SPL")
405	}
