408	// Audit helpers
409	// ---------------------------------------------------------------------------
410	
411	fn emit_print_audit(
412	    ctx: &EmitContext,
413	    job: &JobInfo,
414	    event_type: EventType,
415	    decision: Decision,
416	    _reason: &str,
417	) {
418	    let mut event = AuditEvent::new(
419	        event_type,
420	        "S-1-0-0".to_string(), // Placeholder SID
421	        job.user_name.clone(),
422	        job.document_name.clone(),
423	        Classification::T1, // Classification is in the request, not the event directly
424	        Action::PRINT,
425	        decision,
426	        ctx.agent_id.clone(),
427	        ctx.session_id,
428	    );
429	    event.correlation_id = Some(format!("print-job-{}", job.job_id));
430	    emit_audit(ctx, &mut event);
431	}
