590	    #[test]
591	    fn shutdown_immediately_exits() {
592	        // We can't easily test the thread loop without mocking Win32 APIs,
593	        // but we can verify the shutdown flag works by creating a watcher
594	        // and stopping it immediately.
595	        //
596	        // NOTE: this test requires a tokio runtime.
597	        let rt = tokio::runtime::Runtime::new().unwrap();
598	        let handle = rt.handle().clone();
599	
600	        // Build a minimal OfflineManager (needs a real EngineClient, but we
601	        // only use it in the thread which we stop before it evaluates anything).
602	        let cache = std::sync::Arc::new(crate::cache::Cache::new());
603	        let client = crate::engine_client::EngineClient::default_client().unwrap();
604	        let offline = std::sync::Arc::new(OfflineManager::new(client, cache, None));
605	
606	        let audit_ctx = EmitContext {
607	            agent_id: "AGENT-TEST".to_string(),
608	            session_id: 1,
609	            user_sid: "S-1-5-21-TEST".to_string(),
610	            user_name: "testuser".to_string(),
611	            machine_name: None,
612	        };
613	
614	        let mut watcher = PrintWatcher::new(offline, audit_ctx, handle);
615	        watcher.config = PrintWatcherConfig {
616	            max_pages: 0,
617	            ..Default::default()
618	        };
619	
620	        // We can't start the real watcher in a unit test because it calls
621	        // OpenPrinter on the spooler.  Instead, verify the struct state.
622	        assert!(watcher.handle.is_none());
623	        watcher.shutdown.store(true, Ordering::Relaxed);
624	        assert!(watcher.shutdown.load(Ordering::Relaxed));
625	    }
